# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def _student(last, first, number="1"):
    return Student(number, last, first, "A")


class SeatingRowsTests(unittest.TestCase):
    def test_sorts_by_last_name_and_fills_rows(self):
        students = [_student("Halloway", "Juno"), _student("Dunmere", "Piet")]
        self.assertEqual(seating_rows(students, 2), ["Row 1: Dunmere, Piet | Halloway, Juno"])

    def test_last_row_may_be_short(self):
        students = [_student(name, "X") for name in ("C", "A", "B")]
        self.assertEqual(seating_rows(students, 2), ["Row 1: A, X | B, X", "Row 2: C, X"])

    def test_first_name_breaks_ties(self):
        students = [_student("Lee", "Zoe"), _student("Lee", "Al")]
        self.assertEqual(seating_rows(students, 5), ["Row 1: Lee, Al | Lee, Zoe"])

    def test_non_positive_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([_student("A", "B")], seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
